// ─── File: src/main/java/com/bank/mirror/demo/SourceSinkDemo.java ───
// Models a Source (DB→Kafka, tracks source offset) + two Sinks (Kafka→search / Kafka→DB).
package com.bank.mirror.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SourceSinkDemo {

    private static final Logger log = Logger.getLogger("SourceSink");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountsTable db = new AccountsTable();
        db.insert(new AccountRow(1, "SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        db.insert(new AccountRow(2, "CUR3001", "Priya Sharma", new BigDecimal("250000")));

        Topic topic = new Topic("bank.accounts");
        SearchStore search = new SearchStore();
        ReportStore report = new ReportStore();

        SourceConnector source = new SourceConnector(db, topic);
        SinkConnector searchSink = new SinkConnector(topic, search::index, "search");
        SinkConnector reportSink = new SinkConnector(topic, report::upsert, "report");

        log.info("=== SOURCE: external DB → Kafka (tracks source offset by id) ===");
        source.poll();

        log.info("=== SINK: Kafka → search index AND Kafka → reporting DB ===");
        searchSink.consume();
        reportSink.consume();

        log.info("=== new row + a replay: upsert sink dedups by account_id ===");
        db.insert(new AccountRow(3, "SAV2002", "Amit Verma", new BigDecimal("75000")));
        source.poll();
        reportSink.consume();
        reportSink.replayLast();  // at-least-once replay, upsert keeps one row

        log.info(() -> "topic=" + topic.size() + " searchDocs=" + search.size()
                + " reportRows=" + report.size());
    }
}

// ─── Would be in AccountRow.java ───
class AccountRow {
    final long id; final String accountId; final String holder; final BigDecimal balance;
    AccountRow(long id, String accountId, String holder, BigDecimal balance) {
        this.id = id; this.accountId = accountId; this.holder = holder; this.balance = balance;
    }
}

// ─── Would be in AccountsTable.java (external source system) ───
class AccountsTable {
    private final List<AccountRow> rows = new ArrayList<>();
    void insert(AccountRow r) { rows.add(r); }
    List<AccountRow> newerThan(long lastId) {
        List<AccountRow> out = new ArrayList<>();
        for (AccountRow r : rows) if (r.id > lastId) out.add(r);
        return out;
    }
}

// ─── Would be in Topic.java ───
class Topic {
    private final String name; private final List<AccountRow> records = new ArrayList<>();
    Topic(String name) { this.name = name; }
    void append(AccountRow r) { records.add(r); }
    List<AccountRow> from(int offset) {
        return new ArrayList<>(records.subList(offset, records.size()));
    }
    AccountRow last() { return records.get(records.size() - 1); }
    int size() { return records.size(); }
    String name() { return name; }
}

// ─── Would be in SearchStore.java (external sink target) ───
class SearchStore {
    private static final Logger log = Logger.getLogger("SourceSink");
    private int docs = 0;
    void index(AccountRow r) { docs++; log.info(() -> "indexed doc account=" + r.accountId); }
    int size() { return docs; }
}

// ─── Would be in ReportStore.java (external sink target, upsert keyed) ───
class ReportStore {
    private static final Logger log = Logger.getLogger("SourceSink");
    private final Map<String, AccountRow> byAccount = new LinkedHashMap<>();
    void upsert(AccountRow r) {
        boolean existed = byAccount.containsKey(r.accountId);
        byAccount.put(r.accountId, r);     // upsert by account_id → replay-safe
        log.info(() -> (existed ? "updated" : "inserted") + " report row account=" + r.accountId);
    }
    int size() { return byAccount.size(); }
}

// ─── Would be in SourceConnector.java (external → Kafka, tracks SOURCE offset) ───
class SourceConnector {
    private static final Logger log = Logger.getLogger("SourceSink");
    private final AccountsTable db; private final Topic topic;
    private long sourceOffsetLastId = 0;   // position in the EXTERNAL system
    SourceConnector(AccountsTable db, Topic topic) { this.db = db; this.topic = topic; }
    void poll() {
        for (AccountRow r : db.newerThan(sourceOffsetLastId)) {
            topic.append(r);
            sourceOffsetLastId = r.id;
            log.info(() -> "source produced id=" + r.id + " to " + topic.name());
        }
    }
}

// ─── Would be in SinkConnector.java (Kafka → external, tracks KAFKA offset) ───
class SinkConnector {
    private static final Logger log = Logger.getLogger("SourceSink");
    private final Topic topic; private final java.util.function.Consumer<AccountRow> writer;
    private final String name; private int kafkaOffset = 0;   // position in KAFKA
    SinkConnector(Topic topic, java.util.function.Consumer<AccountRow> writer, String name) {
        this.topic = topic; this.writer = writer; this.name = name;
    }
    void consume() {
        List<AccountRow> pending = topic.from(kafkaOffset);
        for (AccountRow r : pending) writer.accept(r);   // write to target FIRST
        kafkaOffset += pending.size();                   // THEN commit offset
        log.fine(() -> name + " sink committed offset=" + kafkaOffset);
    }
    void replayLast() {
        // simulate at-least-once redelivery of the last record
        log.warning(() -> name + " sink REPLAY last record (at-least-once)");
        writer.accept(topic.last());
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
